do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'spanish-2';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 21, $j$6.1 Telling Bible Stories in Spanish$j$, $j${"readings": [{"title": "Psalm 78 (King James Version)", "url": "/portal/bible/Psalms/78"}], "body": "Psalm 78:4 says, We will not hide them from their children, shewing to the generation to come the praises of the LORD, and his strength, and his wonderful works that he hath done. Telling the stories of God in Spanish lets you share them with a Spanish speaking child, neighbor or friend. You now have the tools: the preterite for events and the imperfect for the scene.\n\nUseful story words are la historia, el relato, el ángel, los pastores, el pastor, el rey, el profeta, el discípulo, el milagro, la cruz, la tumba, el cielo, la tierra, nació, murió, resucitó, dijo, creó, llamó and sanó.\n\nBuild a story in four steps. First, set the scene with the imperfect: Había un hombre que se llamaba Zaqueo, y era pequeño. Second, tell what happened with the preterite: Jesús pasó por la ciudad, vio a Zaqueo y le dijo que bajara. Third, show the result: Zaqueo recibió a Jesús con alegría. Fourth, state the lesson: Jesús vino a buscar y a salvar lo que se había perdido.\n\nWorked example: Dios creó los cielos y la tierra. Al principio todo estaba oscuro, pero Dios dijo: Sea la luz. Common mistake: using the present tense for a past story, or using a translation tool and copying it. Write the sentences yourself and have a fluent speaker or teacher check them.\n\nYour task: (1) Tell a Bible story of at least eight sentences in Spanish using both the preterite and the imperfect. (2) Underline each preterite and circle each imperfect.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Psalm 78:4 says, We will not hide them from their children, shewing to the generation to come the praises of the LORD. Telling Bible stories in Spanish is one way to do that.\n\nNow watch this. Story words: la historia, el ángel, los pastores, el rey, el profeta, el milagro, la cruz, la tumba. Verbs: nació, murió, resucitó, dijo, creó, llamó, sanó.\n\nBuild a story in four steps. Set the scene with the imperfect. Tell what happened with the preterite. Show the result. State the lesson.\n\nDios creó los cielos y la tierra. Todo estaba oscuro, pero Dios dijo: Sea la luz.\n\nWrite the story yourself, and have a fluent speaker check it.\n\nYour task is to tell a Bible story in eight Spanish sentences and mark each tense. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.1 Telling Bible Stories in Spanish$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 22, $j$6.2 Prayer, Testimony and Hospitality$j$, $j${"readings": [{"title": "Philippians 4 (King James Version)", "url": "/portal/bible/Philippians/4"}], "body": "Philippians 4:6 says, Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God. Many Spanish speaking believers pray out loud with great warmth, and you can learn to pray with them.\n\nIn Spanish prayers, believers usually address God with the familiar forms tú, te and ti as a sign of closeness and love. Useful phrases are Oremos (let us pray), Padre celestial, Señor Jesús, te damos gracias por, te pedimos que, bendice a, en el nombre de Jesús and amén. The phrase te pedimos que is followed by a special verb form called the subjunctive, which you will study in Spanish 3, so for now learn the phrases as a set: te pedimos que nos ayudes.\n\nA testimony tells what God has done. Use the imperfect and the preterite: Antes yo estaba perdido, pero un día encontré a Jesús, y ahora tengo paz. Add time words: antes, un día, ahora.\n\nHospitality uses formal courtesy. Bienvenido (to one man), bienvenida (to one woman) and bienvenidos (to a group). ¿Puedo orar por usted? ¿Necesita algo? Estamos para servirle. Gracias por visitarnos. Vuelva pronto.\n\nWorked example: Bienvenidos a nuestra iglesia. ¿Puedo orar por usted? Oremos: Padre celestial, te damos gracias por este día. En el nombre de Jesús, amén. Common mistake: praying with memorized words you do not understand. Learn what each phrase means.\n\nYour task: (1) Write a three sentence Spanish welcome for visitors. (2) Write a testimony of five sentences using antes, un día and ahora.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Philippians 4:6 says, In every thing by prayer and supplication with thanksgiving let your requests be made known unto God. Let us learn to pray in Spanish.\n\nNow watch this. Spanish believers usually address God as tú, a sign of closeness. Phrases: Oremos. Padre celestial. Te damos gracias por. Te pedimos que. En el nombre de Jesús. Amén.\n\nA testimony: Antes yo estaba perdido, pero un día encontré a Jesús, y ahora tengo paz.\n\nHospitality: Bienvenido, bienvenida, bienvenidos. ¿Puedo orar por usted? ¿Necesita algo? Estamos para servirle. Vuelva pronto.\n\nLearn what each phrase means before you use it.\n\nYour task is to write a welcome for visitors and a five sentence testimony. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.2 Prayer, Testimony and Hospitality$j$);
end
$seed$;
